#include "stdlib/math/base/special/acoshf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/sqrtf.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/log1pf.h"
#include <stdint.h>

static const float ONE = 1.0;
static const float LN2 = 6.9314718246e-01;  /* 0x3f317218 */

/**
* Computes the arc hyperbolic cosine of a single-precision floating-point number.
*
* @param x    input value
* @return     arccosine (in radians)
*
* @example
* float out = stdlib_base_acoshf( 1.0f );
* // returns 0.0f
*/
float stdlib_base_acoshf( float x ) {
	float t;
	uint32_t hx;

	if ( stdlib_base_is_nanf( x ) || x < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	stdlib_base_float32_to_word( x, &hx );
	if( hx < 0x3f800000 ) { /* x < 1 */
		return ( x - x ) / ( x - x  );
	} else if ( hx >= 0x4d800000 ) { /* x > 2**28 */
		if ( hx >= 0x7f800000 ) { /* x is inf of NaN */
			return x+x;
		} else {
			return stdlib_base_lnf( x ) + LN2 ; /* acosh(huge)=log(2x) */
		}
	} else if ( hx == 0x3f800000 ) {
		return 0.0; /* acosh(1) = 0 */
	} else if ( hx > 0x40000000 ) { /* 2**28 > x > 2 */
		t = x * x;
		return stdlib_base_lnf( ( (float)2.0 * x ) - ( ONE / ( x + stdlib_base_sqrtf( t - ONE ) ) ) );
	} else {  /* 1<x<2 */
		t = x - ONE;
		return stdlib_base_log1pf( t + stdlib_base_sqrtf( (float)2.0 * t + t * t ) );
	}
}
